def minPath(grid, k):
    n = len(grid)

    # Find the position of value 1
    start_pos = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start_pos = (i, j)
                break
        if start_pos:
            break

    # DFS to find the lexicographically smallest path
    def dfs(row, col, path, remaining):
        if remaining == 0:
            return path

        # Explore all four neighbors
        neighbors = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = row + dr, col + dc
            if 0 <= nr < n and 0 <= nc < n:
                neighbors.append((grid[nr][nc], nr, nc))

        # Sort neighbors by their values to explore in lexicographically smallest order
        neighbors.sort()

        best_path = None
        for val, nr, nc in neighbors:
            new_path = path + [val]
            result = dfs(nr, nc, new_path, remaining - 1)

            if best_path is None or result < best_path:
                best_path = result

        return best_path

    # Start DFS from position of 1
    result = dfs(start_pos[0], start_pos[1], [1], k - 1)
    return result

def solve(s):
    # Check if string contains any letters
    has_letter = any(c.isalpha() for c in s)

    if not has_letter:
        # If no letters, reverse the string
        return s[::-1]
    else:
        # If has letters, swap case of letters and keep others as is
        return ''.join(c.swapcase() if c.isalpha() else c for c in s)

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    result = [word for word in words if is_prime(len(word))]
    return " ".join(result)

def encode_shift(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    return "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])


def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    even_count = 0
    odd_count = 0

    for digit_char in str(abs(num)):
        digit = int(digit_char)
        if digit % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return (even_count, odd_count)

def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd
    integer palindromes that fall within the range(1, n), inclusive.
    """
    def is_palindrome(num):
        s = str(num)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)
